"use client";

import * as React from "react";
import {
  Alert,
  AlertDescription,
  AlertTitle,
  AmountBreakdown,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Checkbox,
  CheckList,
  Cluster,
  DatePicker,
  Delta,
  DesktopPageHeader,
  ExpiryBadge,
  FormControl,
  FormDescription,
  FormField,
  FormLabel,
  FormMessage,
  Grid,
  Input,
  MetadataList,
  RadioGroup,
  RadioGroupItem,
  SegmentedControl,
  Select,
  Separator,
  StatGroup,
  Statistic,
  Stepper,
  Switch,
  VStack,
  formatCurrency,
  type AmountLine,
} from "@gunjo/ui";
import { IconAlertTriangle, IconCircleCheck } from "@tabler/icons-react";
import { ja } from "date-fns/locale";

import { PlanComparison, type PlanView } from "./PlanComparison";
import { QuoteList, type ListDisplayState } from "./QuoteList";
import {
  BODILY_INJURY,
  CLASS_FACTOR,
  DEDUCTIBLE_FIRST,
  DEDUCTIBLE_SECOND,
  GRADES,
  LICENSE_COLORS,
  MILEAGE_OPTIONS,
  PERSONAL_INJURY,
  PLAN_PRESETS,
  PROPERTY_DAMAGE,
  QUOTE_ROWS,
  RIDERS,
  SAFETY_DEVICES,
  TODAY,
  USE_OPTIONS,
  VEHICLE_COVER,
  VEHICLE_MODELS,
  agreedValue,
  ageInMonths,
  calcPremium,
  expiryFromToday,
  findModel,
  gradeRate,
  parseLocalDate,
  todayDate,
  type CoverageConfig,
  type LicenseColor,
  type MileageBand,
  type PlanPreset,
  type PolicyholderInput,
  type QuoteRow,
  type VehicleInput,
  type VehicleUse,
} from "./pricing";

/* ------------------------------------------------------------- 小さな道具 */

function parseISODate(value: string): Date | undefined {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return undefined;
  return parseLocalDate(value);
}

function toISODate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function ageAt(birth: string): number | null {
  const b = parseISODate(birth);
  if (!b) return null;
  const base = todayDate();
  let age = base.getFullYear() - b.getFullYear();
  const beforeBirthday =
    base.getMonth() < b.getMonth() || (base.getMonth() === b.getMonth() && base.getDate() < b.getDate());
  if (beforeBirthday) age -= 1;
  return age;
}

function signedPercent(rate: number): string {
  if (rate === 0) return "±0%";
  const sign = rate > 0 ? "＋" : "−";
  return `${sign}${Math.abs(Math.round(rate * 1000) / 10)}%`;
}

const REGISTRATION_YEARS = Array.from({ length: 19 }, (_, i) => 2026 - i);
const MONTHS = Array.from({ length: 12 }, (_, i) => i + 1);

/* --------------------------------------------------------------- 初期状態 */

const INITIAL_HOLDER: PolicyholderInput = {
  name: "相馬 千尋",
  birthDate: "1988-05-12",
  licenseColor: "gold",
  grade: 14,
  hadAccident: false,
};

const INITIAL_VEHICLE: VehicleInput = {
  modelCode: "MTB-5S40",
  firstRegYear: 2022,
  firstRegMonth: 6,
  use: "private",
  mileage: "u5000",
  safety: ["asv"],
};

/* -------------------------------------------------------------- 画面本体 */

export default function QuotationPage() {
  const [holder, setHolder] = React.useState<PolicyholderInput>(INITIAL_HOLDER);
  const [vehicle, setVehicle] = React.useState<VehicleInput>(INITIAL_VEHICLE);
  const [coverage, setCoverage] = React.useState<CoverageConfig>(PLAN_PRESETS[1].coverage);
  const [paperless, setPaperless] = React.useState(true);

  const [displayState, setDisplayState] = React.useState<ListDisplayState>("data");
  const [editing, setEditing] = React.useState<QuoteRow | null>(null);
  const [issued, setIssued] = React.useState(0);
  const [confirmed, setConfirmed] = React.useState<{
    number: string;
    expiresAt: string;
    annual: number;
  } | null>(null);

  /* 条件を1つでも変えたら、確定済みの見積番号は無効に戻します。 */
  const patchHolder = (patch: Partial<PolicyholderInput>) => {
    setHolder((prev) => ({ ...prev, ...patch }));
    setConfirmed(null);
  };
  const patchVehicle = (patch: Partial<VehicleInput>) => {
    setVehicle((prev) => ({ ...prev, ...patch }));
    setConfirmed(null);
  };
  const patchCoverage = (patch: Partial<CoverageConfig>) => {
    setCoverage((prev) => ({ ...prev, ...patch }));
    setConfirmed(null);
  };

  const model = findModel(vehicle.modelCode);
  const months = ageInMonths(vehicle.firstRegYear, vehicle.firstRegMonth);
  const hasVehicleCover = coverage.vehicleCover !== "none";

  const result = React.useMemo(
    () => calcPremium(coverage, vehicle, holder, { paperless }),
    [coverage, vehicle, holder, paperless],
  );

  const plans: PlanView[] = React.useMemo(
    () =>
      PLAN_PRESETS.map((preset) => ({
        preset,
        result: calcPremium(preset.coverage, vehicle, holder, { paperless }),
      })),
    [vehicle, holder, paperless],
  );

  const nameMissing = holder.name.trim().length === 0;
  const age = ageAt(holder.birthDate);

  /* ------------------------------------------------------- 内訳の行を組む */

  const breakdownLines: AmountLine[] = React.useMemo(() => {
    const lines: AmountLine[] = [];
    const push = (list: typeof result.coverageLines) => {
      for (const line of list) {
        lines.push({
          label: line.label,
          note: line.note,
          amount: Math.abs(line.amount),
          kind: line.kind,
        });
      }
    };

    lines.push({ type: "heading", label: "1. 補償ごとの基準保険料" });
    push(result.coverageLines);
    lines.push({ type: "subtotal", label: "補償の基準保険料 小計", amount: result.coverageSubtotal });

    lines.push({ type: "heading", label: "2. 契約条件による調整" });
    push(result.conditionLines);
    lines.push({
      type: "subtotal",
      label: "基本保険料（等級・割引の適用前）",
      amount: result.baseBeforeGrade,
    });

    lines.push({ type: "heading", label: "3. 等級と各割引" });
    push(result.discountLines);
    lines.push({ type: "subtotal", label: "基本保険料", amount: result.basePremium });

    lines.push({ type: "heading", label: `4. 特約（${result.appliedRiders.length}件）` });
    if (result.riderLines.length === 0) {
      lines.push({ label: "特約は付けていません", amount: 0 });
    } else {
      push(result.riderLines);
    }
    lines.push({ type: "subtotal", label: "特約 計", amount: result.riderTotal });

    lines.push({ type: "heading", label: "5. 定額の割引" });
    if (result.fixedLines.length === 0) {
      lines.push({ label: "対象の割引はありません", amount: 0 });
    } else {
      push(result.fixedLines);
    }

    return lines;
  }, [result]);

  /* --------------------------------------------------------- 一覧との連携 */

  const openQuote = (row: QuoteRow) => {
    setEditing(row);
    setConfirmed(null);
    setHolder((prev) => ({ ...prev, name: row.contractor }));
    setVehicle((prev) => ({ ...prev, modelCode: row.modelCode }));
  };

  const createNew = () => {
    setEditing(null);
    setConfirmed(null);
    setHolder({ ...INITIAL_HOLDER, name: "" });
    setVehicle(INITIAL_VEHICLE);
    setCoverage(PLAN_PRESETS[1].coverage);
  };

  const applyPlan = (preset: PlanPreset) => {
    setCoverage(preset.coverage);
    setConfirmed(null);
  };

  const confirmQuote = () => {
    const seq = 842 + issued;
    setIssued((n) => n + 1);
    setConfirmed({
      number: `MQ-2026-${String(seq).padStart(5, "0")}`,
      expiresAt: expiryFromToday(30),
      annual: result.annual,
    });
  };

  const steps = [
    {
      label: "契約者と車両の入力",
      state: nameMissing ? ("current" as const) : ("completed" as const),
    },
    {
      label: "補償と保険料の確認",
      state: nameMissing ? ("upcoming" as const) : confirmed ? ("completed" as const) : ("current" as const),
    },
    {
      label: "見積の確定",
      state: confirmed ? ("completed" as const) : ("upcoming" as const),
    },
  ];

  return (
    <main className="min-h-dvh bg-background text-foreground">
      <div className="mx-auto w-full max-w-[1400px] px-4 py-8 sm:px-6 lg:px-8">
        <VStack gap={10}>
          <DesktopPageHeader
            eyebrow="みなも損害保険 ／ カナデ保険サービス（いずれも架空）"
            title="自動車保険 見積作成"
            subtitle="基準日 2026/08/25 ／ 担当 榊 直人。料率・割引率はこの画面のためのデモ値です。"
            actions={<Badge variant="outline">デモ用の架空データ</Badge>}
          />

          {/* ---------------------------------------------------- 見積の一覧 */}
          <section aria-labelledby="sec-list">
            <VStack gap={4}>
              <h2 id="sec-list" className="text-xl font-semibold">
                見積の一覧
              </h2>
              <QuoteList
                rows={displayState === "empty" ? [] : QUOTE_ROWS}
                displayState={displayState}
                onOpen={openQuote}
                onCreate={createNew}
                toolbar={
                  <div className="rounded-lg border border-dashed border-border p-3">
                    <VStack gap={2}>
                      <span className="text-xs font-medium text-muted-foreground">
                        表示の確認用（この切り替えは実運用にはありません）
                      </span>
                      <SegmentedControl
                        aria-label="一覧の表示状態を切り替える"
                        value={displayState}
                        onValueChange={(v) => setDisplayState(v as ListDisplayState)}
                        options={[
                          { value: "data", label: "見積あり" },
                          { value: "loading", label: "読み込み中" },
                          { value: "empty", label: "0件" },
                        ]}
                      />
                    </VStack>
                  </div>
                }
              />
            </VStack>
          </section>

          {/* ---------------------------------------------------- 見積を作る */}
          <section aria-labelledby="sec-build">
            <VStack gap={4}>
              <h2 id="sec-build" className="text-xl font-semibold">
                見積を作る
              </h2>
              <Cluster justify="between" align="center" gap={3}>
                <p className="text-sm text-muted-foreground">
                  {editing
                    ? `一覧の ${editing.number}（${editing.contractor} 様）を読み込んでいます。`
                    : "新しい見積を作っています。一覧の行を選ぶと、その見積を読み込みます。"}
                </p>
                {editing ? <Badge variant="secondary">{editing.number}</Badge> : <Badge variant="outline">新規</Badge>}
              </Cluster>
              <Stepper steps={steps} aria-label="見積作成の進み方" />

              <div className="grid grid-cols-1 gap-6 lg:grid-cols-[minmax(0,1fr)_20rem]">
                <VStack gap={6}>
                  {/* ------------------------------------ 契約者の情報 */}
                  <Card>
                    <CardHeader>
                      <CardTitle as="h3">契約者の情報</CardTitle>
                      <CardDescription>等級と免許証の色は、基本保険料の割引率に直接ひびきます。</CardDescription>
                    </CardHeader>
                    <CardContent>
                      <Grid cols={{ base: 1, md: 2 }} gap={4}>
                        <FormField
                          className="p-0"
                          required
                          error={nameMissing ? "氏名を入れてください。" : undefined}
                        >
                          <FormLabel>氏名</FormLabel>
                          <FormControl>
                            <Input
                              value={holder.name}
                              onChange={(e) => patchHolder({ name: e.target.value })}
                              placeholder="例：相馬 千尋"
                              autoComplete="off"
                            />
                          </FormControl>
                          <FormDescription>見積書に印字される名前です。</FormDescription>
                          <FormMessage />
                        </FormField>

                        <DatePicker
                          label="生年月日"
                          value={parseISODate(holder.birthDate)}
                          onValueChange={(d) => patchHolder({ birthDate: d ? toISODate(d) : "" })}
                          dateFormat="yyyy/MM/dd"
                          placeholder="yyyy/mm/dd"
                          locale={ja}
                          startMonth={new Date(1930, 0, 1)}
                          endMonth={new Date(2010, 11, 31)}
                          description={
                            age === null ? "数字8桁でも入力できます。" : `基準日で ${age} 歳。数字8桁でも入力できます。`
                          }
                        />

                        <div className="flex flex-col gap-1.5">
                          <span id="license-color-label" className="text-sm font-medium leading-none">
                            運転免許の色
                          </span>
                          <RadioGroup
                            aria-labelledby="license-color-label"
                            value={holder.licenseColor}
                            onValueChange={(v) => patchHolder({ licenseColor: v as LicenseColor })}
                          >
                            {LICENSE_COLORS.map((c) => (
                              <RadioGroupItem
                                key={c.value}
                                value={c.value}
                                label={c.label}
                                description={
                                  c.rate === 0 ? "割引はありません" : `基本保険料から ${signedPercent(c.rate)}`
                                }
                              />
                            ))}
                          </RadioGroup>
                        </div>

                        <VStack gap={4}>
                          <Select
                            label="ノンフリート等級"
                            value={String(holder.grade)}
                            onChange={(e) => patchHolder({ grade: Number(e.target.value) })}
                            description={`いまの等級の調整率は ${signedPercent(gradeRate(holder.grade, holder.hadAccident))} です。`}
                          >
                            {GRADES.map((g) => (
                              <option key={g} value={g}>
                                {g}等級（{signedPercent(gradeRate(g, holder.hadAccident))}）
                              </option>
                            ))}
                          </Select>

                          <div className="flex flex-col gap-1.5">
                            <span className="text-sm font-medium leading-none">前年の事故</span>
                            <SegmentedControl
                              aria-label="前年の事故の有無"
                              value={holder.hadAccident ? "yes" : "no"}
                              onValueChange={(v) => patchHolder({ hadAccident: v === "yes" })}
                              options={[
                                { value: "no", label: "なし" },
                                { value: "yes", label: "あり" },
                              ]}
                            />
                            <p className="text-xs text-muted-foreground">
                              事故があると、同じ等級でも割引率が小さくなります。
                            </p>
                          </div>
                        </VStack>
                      </Grid>
                    </CardContent>
                  </Card>

                  {/* ------------------------------------ 車両の情報 */}
                  <Card>
                    <CardHeader>
                      <CardTitle as="h3">車両の情報</CardTitle>
                      <CardDescription>
                        型式ごとに補償別の料率クラスが決まっていて、それが基準保険料の倍率になります。
                      </CardDescription>
                    </CardHeader>
                    <CardContent>
                      <VStack gap={4}>
                        <Grid cols={{ base: 1, md: 2 }} gap={4}>
                          <Select
                            label="型式"
                            value={vehicle.modelCode}
                            onChange={(e) => patchVehicle({ modelCode: e.target.value })}
                            description={`${model.segment} ／ 新車価格相当 ${formatCurrency(model.newPrice)}`}
                          >
                            {VEHICLE_MODELS.map((m) => (
                              <option key={m.code} value={m.code}>
                                {m.code}（{m.segment}）
                              </option>
                            ))}
                          </Select>

                          <fieldset className="flex flex-col gap-1.5">
                            <legend className="text-sm font-medium leading-none">初度登録年月</legend>
                            <Grid cols={2} gap={2}>
                              <Select
                                aria-label="初度登録の年"
                                value={String(vehicle.firstRegYear)}
                                onChange={(e) => patchVehicle({ firstRegYear: Number(e.target.value) })}
                              >
                                {REGISTRATION_YEARS.map((y) => (
                                  <option key={y} value={y}>
                                    {y}年
                                  </option>
                                ))}
                              </Select>
                              <Select
                                aria-label="初度登録の月"
                                value={String(vehicle.firstRegMonth)}
                                onChange={(e) => patchVehicle({ firstRegMonth: Number(e.target.value) })}
                              >
                                {MONTHS.map((m) => (
                                  <option key={m} value={m}>
                                    {m}月
                                  </option>
                                ))}
                              </Select>
                            </Grid>
                            <p className="text-xs text-muted-foreground">
                              基準日まで {months} か月。25か月以内なら新車割引の対象です。
                            </p>
                          </fieldset>

                          <div className="flex flex-col gap-1.5">
                            <span className="text-sm font-medium leading-none">用途</span>
                            <SegmentedControl
                              aria-label="車の用途"
                              value={vehicle.use}
                              onValueChange={(v) => patchVehicle({ use: v as VehicleUse })}
                              options={USE_OPTIONS.map((o) => ({
                                value: o.value,
                                label: `${o.label}（×${o.factor.toFixed(2)}）`,
                              }))}
                            />
                          </div>

                          <Select
                            label="年間走行距離の区分"
                            value={vehicle.mileage}
                            onChange={(e) => patchVehicle({ mileage: e.target.value as MileageBand })}
                            description="補償の合計額にこの係数を掛けます。"
                          >
                            {MILEAGE_OPTIONS.map((o) => (
                              <option key={o.value} value={o.value}>
                                {o.label}（×{o.factor.toFixed(2)}）
                              </option>
                            ))}
                          </Select>
                        </Grid>

                        <fieldset className="flex flex-col gap-2">
                          <legend className="mb-1 text-sm font-medium leading-none">安全装置</legend>
                          {SAFETY_DEVICES.map((d) => {
                            const blocked = d.needsVehicleCover && !hasVehicleCover;
                            return (
                              <Checkbox
                                key={d.id}
                                checked={vehicle.safety.includes(d.id)}
                                disabled={blocked}
                                onCheckedChange={(checked) =>
                                  patchVehicle({
                                    safety: checked
                                      ? [...vehicle.safety, d.id]
                                      : vehicle.safety.filter((id) => id !== d.id),
                                  })
                                }
                                label={d.label}
                                description={blocked ? "車両保険を付けると選べます。" : d.description}
                              />
                            );
                          })}
                        </fieldset>

                        <Separator />

                        <MetadataList
                          wrap
                          items={[
                            {
                              label: "型式別料率クラス",
                              value: `対人 ${model.cls.bi} ／ 対物 ${model.cls.pd} ／ 傷害 ${model.cls.pi} ／ 車両 ${model.cls.veh}`,
                              description: `係数は 対人 ×${CLASS_FACTOR[model.cls.bi]} ／ 対物 ×${CLASS_FACTOR[model.cls.pd]} ／ 傷害 ×${CLASS_FACTOR[model.cls.pi]} ／ 車両 ×${CLASS_FACTOR[model.cls.veh]}`,
                            },
                            {
                              label: "協定保険価額",
                              value: formatCurrency(agreedValue(model.newPrice, months)),
                              description: `新車価格相当 ${formatCurrency(model.newPrice)} から、1年あたり 14% 減（下限は 15%）で算出`,
                            },
                          ]}
                        />
                      </VStack>
                    </CardContent>
                  </Card>

                  {/* ------------------------------------ 補償の組み立て */}
                  <Card>
                    <CardHeader>
                      <CardTitle as="h3">補償の組み立て</CardTitle>
                      <CardDescription>変えるたびに、右の保険料と下の内訳がその場で計算し直されます。</CardDescription>
                    </CardHeader>
                    <CardContent>
                      <VStack gap={6}>
                        <VStack gap={3}>
                          <h4 className="text-sm font-semibold">基本の4補償</h4>
                          <Grid cols={{ base: 1, md: 2 }} gap={4}>
                            <Select
                              label="対人賠償"
                              value={coverage.bodilyInjury}
                              onChange={(e) =>
                                patchCoverage({ bodilyInjury: e.target.value as CoverageConfig["bodilyInjury"] })
                              }
                              description={`基準 ${formatCurrency(
                                BODILY_INJURY.find((o) => o.value === coverage.bodilyInjury)?.base ?? 0,
                              )} × 料率クラス${model.cls.bi}`}
                            >
                              {BODILY_INJURY.map((o) => (
                                <option key={o.value} value={o.value}>
                                  {o.label}
                                </option>
                              ))}
                            </Select>

                            <Select
                              label="対物賠償"
                              value={coverage.propertyDamage}
                              onChange={(e) =>
                                patchCoverage({ propertyDamage: e.target.value as CoverageConfig["propertyDamage"] })
                              }
                              description={`基準 ${formatCurrency(
                                PROPERTY_DAMAGE.find((o) => o.value === coverage.propertyDamage)?.base ?? 0,
                              )} × 料率クラス${model.cls.pd}`}
                            >
                              {PROPERTY_DAMAGE.map((o) => (
                                <option key={o.value} value={o.value}>
                                  {o.label}
                                </option>
                              ))}
                            </Select>

                            <Select
                              label="人身傷害"
                              value={coverage.personalInjury}
                              onChange={(e) =>
                                patchCoverage({ personalInjury: e.target.value as CoverageConfig["personalInjury"] })
                              }
                              description={`基準 ${formatCurrency(
                                PERSONAL_INJURY.find((o) => o.value === coverage.personalInjury)?.base ?? 0,
                              )} × 料率クラス${model.cls.pi}`}
                            >
                              {PERSONAL_INJURY.map((o) => (
                                <option key={o.value} value={o.value}>
                                  {o.label}
                                </option>
                              ))}
                            </Select>

                            <Select
                              label="車両保険"
                              value={coverage.vehicleCover}
                              onChange={(e) =>
                                patchCoverage({ vehicleCover: e.target.value as CoverageConfig["vehicleCover"] })
                              }
                              description={
                                hasVehicleCover
                                  ? `協定保険価額 ${formatCurrency(agreedValue(model.newPrice, months))} × 料率 × クラス${model.cls.veh}`
                                  : "付けない場合、車両の損害と一部の特約は対象外です。"
                              }
                            >
                              {VEHICLE_COVER.map((o) => (
                                <option key={o.value} value={o.value}>
                                  {o.label}
                                </option>
                              ))}
                            </Select>
                          </Grid>
                        </VStack>

                        <VStack gap={3}>
                          <h4 className="text-sm font-semibold">免責金額（車両保険の自己負担）</h4>
                          <Grid cols={{ base: 1, md: 2 }} gap={4}>
                            <Select
                              label="1回目の事故"
                              disabled={!hasVehicleCover}
                              value={String(coverage.deductibleFirst)}
                              onChange={(e) => patchCoverage({ deductibleFirst: Number(e.target.value) })}
                              description={
                                hasVehicleCover
                                  ? `車両保険料を ${signedPercent(
                                      DEDUCTIBLE_FIRST.find((d) => d.value === coverage.deductibleFirst)?.rate ?? 0,
