export interface PlanView {
  preset: PlanPreset;
  result: PremiumResult;
}

interface CompareRow {
  key: string;
  label: string;
  values: string[];
  differs: boolean;
  emphasis?: boolean;
}

function label<T extends string>(options: { value: T; label: string }[], value: T): string {
  return options.find((o) => o.value === value)?.label ?? "—";
}

function riderSummary(plan: PlanView): string {
  const names = plan.result.appliedRiders.map((r) => r.label);
  if (names.length === 0) return "付けない";
  return `${names.length}件：${names.join("・")}`;
}

function buildRows(plans: PlanView[]): CompareRow[] {
  const raw: Omit<CompareRow, "differs">[] = [
    { key: "bi", label: "対人賠償", values: plans.map((p) => label(BODILY_INJURY, p.preset.coverage.bodilyInjury)) },
    { key: "pd", label: "対物賠償", values: plans.map((p) => label(PROPERTY_DAMAGE, p.preset.coverage.propertyDamage)) },
    { key: "pi", label: "人身傷害", values: plans.map((p) => label(PERSONAL_INJURY, p.preset.coverage.personalInjury)) },
    { key: "veh", label: "車両保険", values: plans.map((p) => label(VEHICLE_COVER, p.preset.coverage.vehicleCover)) },
    {
      key: "ded1",
      label: "免責金額（1回目の事故）",
      values: plans.map((p) =>
        p.preset.coverage.vehicleCover === "none"
          ? "車両保険なし"
          : label(DEDUCTIBLE_FIRST.map((d) => ({ value: String(d.value), label: d.label })), String(p.preset.coverage.deductibleFirst)),
      ),
    },
    {
      key: "ded2",
      label: "免責金額（2回目以降の事故）",
      values: plans.map((p) =>
        p.preset.coverage.vehicleCover === "none"
          ? "車両保険なし"
          : label(DEDUCTIBLE_SECOND.map((d) => ({ value: String(d.value), label: d.label })), String(p.preset.coverage.deductibleSecond)),
      ),
    },
    { key: "riders", label: "特約", values: plans.map(riderSummary) },
    {
      key: "riderTotal",
      label: "特約の保険料",
      values: plans.map((p) => formatCurrency(p.result.riderTotal)),
    },
    {
      key: "base",
      label: "基本保険料（割引後）",
      values: plans.map((p) => formatCurrency(p.result.basePremium)),
    },
    {
      key: "annual",
      label: "年間保険料（年払）",
      values: plans.map((p) => formatCurrency(p.result.annual)),
      emphasis: true,
    },
    {
      key: "monthly",
      label: "月払 1回の額",
      values: plans.map((p) => formatCurrency(p.result.monthly)),
      emphasis: true,
    },
  ];

  return raw.map((row) => ({ ...row, differs: new Set(row.values).size > 1 }));
}

export interface PlanComparisonProps {
  plans: PlanView[];
  onApply: (preset: PlanPreset) => void;
}

export function PlanComparison({ plans, onApply }: PlanComparisonProps) {
  const [onlyDiff, setOnlyDiff] = React.useState(false);
  const rows = React.useMemo(() => buildRows(plans), [plans]);
  const shown = onlyDiff ? rows.filter((r) => r.differs) : rows;
  const sameCount = rows.filter((r) => !r.differs).length;

  const cheapest = Math.min(...plans.map((p) => p.result.annual));
  const priciest = Math.max(...plans.map((p) => p.result.annual));

  return (
    <Card>
      <CardHeader>
        <CardTitle as="h3">3つの案を比べる</CardTitle>
        <CardDescription>
          契約者と車両の条件は3案とも同じです。違うのは補償の組み立てだけで、下の表はその違いを並べたものです。
        </CardDescription>
      </CardHeader>
      <CardContent>
        <VStack gap={4}>
          <Alert variant="info" icon={<IconInfoCircle />}>
            <AlertDescription>
              この画面は、どの案がよいかを決めません。3案は補償の広さと自己負担の置き方が違うだけで、並び順にも優劣の意味はありません。
              年間保険料の幅は {formatCurrency(cheapest)} 〜 {formatCurrency(priciest)}（差は{" "}
              {formatCurrency(priciest - cheapest)}）です。
            </AlertDescription>
          </Alert>

          <Switch
            checked={onlyDiff}
            onCheckedChange={setOnlyDiff}
            label="違いのある項目だけを表示する"
            description={`いま3案で同じ項目は ${sameCount} 件です。`}
          />

          {/* パソコン向け: 項目を縦、案を横に並べた比較表 */}
          <div className="hidden md:block">
            <Table>
              <TableCaption className="sr-only">3つの案の補償と保険料の比較</TableCaption>
              <TableHeader>
                <TableRow>
                  <TableHead scope="col" className="w-56">
                    項目
                  </TableHead>
                  {plans.map((plan) => (
                    <TableHead key={plan.preset.id} scope="col" className="align-top">
                      <VStack gap={1} className="py-1">
                        <span className="text-sm font-semibold text-foreground">{plan.preset.name}</span>
                        <span className="text-xs font-normal leading-snug text-muted-foreground">
                          {plan.preset.policy}
                        </span>
                      </VStack>
                    </TableHead>
                  ))}
                </TableRow>
              </TableHeader>
              <TableBody>
                {shown.map((row) => (
                  <TableRow key={row.key} className={cn(row.differs && "bg-muted/40")}>
                    <TableHead scope="row" className="align-top font-medium">
                      <VStack gap={1} align="start">
                        <span>{row.label}</span>
                        {row.differs ? (
                          <Badge variant="outline" size="sm">
                            3案で違う
                          </Badge>
                        ) : (
                          <span className="text-xs font-normal text-muted-foreground">3案とも同じ</span>
                        )}
                      </VStack>
                    </TableHead>
                    {row.values.map((value, i) => (
                      <TableCell
                        key={plans[i].preset.id}
                        className={cn(
                          "align-top text-sm",
                          row.emphasis && "font-semibold tabular-nums",
                          !row.differs && "text-muted-foreground",
                        )}
                      >
                        {value}
                      </TableCell>
                    ))}
                  </TableRow>
                ))}
                <TableRow>
                  <TableHead scope="row" className="font-medium">
                    この案を使う
                  </TableHead>
                  {plans.map((plan) => (
                    <TableCell key={plan.preset.id} className="align-top">
                      <Button variant="outline" size="sm" onClick={() => onApply(plan.preset)}>
                        {plan.preset.name}を反映
                      </Button>
                    </TableCell>
                  ))}
                </TableRow>
              </TableBody>
            </Table>
          </div>

          {/* スマホ向け: 同じ内容を案ごとに縦積み */}
          <VStack gap={4} className="md:hidden">
            {plans.map((plan, planIndex) => (
              <Card key={plan.preset.id}>
                <CardHeader>
                  <CardTitle as="h4">{plan.preset.name}</CardTitle>
                  <CardDescription>{plan.preset.policy}</CardDescription>
                </CardHeader>
                <CardContent>
                  <VStack gap={3}>
                    <dl className="flex flex-col gap-2">
                      {shown.map((row) => (
                        <div key={row.key} className="flex flex-col gap-0.5 border-t border-border pt-2 first:border-t-0 first:pt-0">
                          <dt className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                            <span>{row.label}</span>
                            {row.differs ? (
                              <Badge variant="outline" size="sm">
                                3案で違う
                              </Badge>
                            ) : (
                              <span>（3案とも同じ）</span>
                            )}
                          </dt>
                          <dd className={cn("text-sm", row.emphasis && "font-semibold tabular-nums")}>
                            {row.values[planIndex]}
                          </dd>
                        </div>
                      ))}
                    </dl>
                    <Button variant="outline" onClick={() => onApply(plan.preset)}>
                      {plan.preset.name}を反映
                    </Button>
                  </VStack>
                </CardContent>
              </Card>
            ))}
          </VStack>
        </VStack>
      </CardContent>
    </Card>
  );
}

/**
 * 自動車保険 見積の料率テーブルと保険料計算。
 *
 * 会社名・代理店名・担当者名・型式・料率・割引率は、すべてこの画面のための架空の値です。
 * 実在する保険会社の商品や料率とは関係ありません。
 *
 * 計算の考え方（画面の「保険料の内訳」と同じ順番）:
 *   1. 補償ごとの基準保険料（型式別料率クラスを反映）
 *   2. 契約条件による調整（車両免責・用途・年間走行距離）  → 基本保険料（等級適用前）
 *   3. 等級と各割引                                       → 基本保険料
 *   4. 特約の保険料を加算
 *   5. 定額の割引を差し引く                                → 年間保険料
 */

/** 画面の基準日。SSR とクライアントで表示がずれないよう固定しています。 */
export const TODAY = "2026-08-25";

/**
 * `YYYY-MM-DD` をその土地の時刻の 0 時として読みます。
 * `new Date("2026-08-25")` は UTC 0 時になり、時差のある環境で日付が1日ずれるため使いません。
 */
export function parseLocalDate(iso: string): Date {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso);
  if (!m) return new Date(NaN);
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}

/** 基準日の Date。 */
export function todayDate(): Date {
  return parseLocalDate(TODAY);
}

/** 10円未満を四捨五入。行の金額はすべてこれを通すので、内訳の足し算が画面上で必ず合います。 */
export function round10(value: number): number {
  return Math.round(value / 10) * 10;
}

