};

/** 同じ等級でも、前年に事故があると割引率が小さくなります（事故有係数）。 */
export const GRADE_RATE_ACCIDENT: Record<number, number> = {
  1: 0.64, 2: 0.28, 3: 0.12, 4: -0.02, 5: -0.13, 6: -0.19, 7: -0.2, 8: -0.21,
