};

export const GRADES: number[] = Array.from({ length: 20 }, (_, i) => i + 1);

export function gradeRate(grade: number, hadAccident: boolean): number {
  const table = hadAccident ? GRADE_RATE_ACCIDENT : GRADE_RATE_CLEAN;
  return table[grade] ?? 0;
}

