/** 初度登録年月から基準日までの経過月数。 */
export function ageInMonths(year: number, month: number): number {
  const base = todayDate();
  return Math.max(0, (base.getFullYear() - year) * 12 + (base.getMonth() + 1 - month));
}

/** 協定保険価額。1年ごとに 14% 落として、下限は新車価格の 15%。 */
export function agreedValue(newPrice: number, months: number): number {
  const ratio = Math.max(0.15, 1 - 0.14 * (months / 12));
  return Math.round((newPrice * ratio) / 10000) * 10000;
}

