/* ---------------------------------------------------------------- 計算結果 */

export interface PremiumLine {
  key: string;
  label: string;
  /** その金額がどこから出たかの一行説明。 */
  note: string;
  amount: number;
  kind: "add" | "subtract";
}

export interface PremiumResult {
  /** 1. 補償ごとの基準保険料 */
  coverageLines: PremiumLine[];
  coverageSubtotal: number;
  /** 2. 契約条件による調整 */
  conditionLines: PremiumLine[];
  baseBeforeGrade: number;
  /** 3. 等級と各割引 */
  discountLines: PremiumLine[];
  basePremium: number;
  /** 4. 特約 */
  riderLines: PremiumLine[];
  riderTotal: number;
  /** 5. 定額の割引 */
  fixedLines: PremiumLine[];
  /** 年払（一時払）の保険料 */
  annual: number;
  /** 月払にしたときの1回の額 */
  monthly: number;
  monthlyYearTotal: number;
  /** 月払12回の合計と年払との差額 */
  monthlyExtra: number;
  agreedValue: number;
  vehicleBase: number;
  appliedRiders: Rider[];
}

function pct(rate: number): string {
  const sign = rate > 0 ? "＋" : "−";
  return `${sign}${Math.abs(Math.round(rate * 1000) / 10)}%`;
}

export interface CalcOptions {
  /** 証券を発行しない場合の定額割引。 */
  paperless: boolean;
}

export function calcPremium(
  coverage: CoverageConfig,
  vehicle: VehicleInput,
  holder: PolicyholderInput,
  options: CalcOptions,
): PremiumResult {
  const model = findModel(vehicle.modelCode);
  const bi = BODILY_INJURY.find((o) => o.value === coverage.bodilyInjury) ?? BODILY_INJURY[0];
  const pd = PROPERTY_DAMAGE.find((o) => o.value === coverage.propertyDamage) ?? PROPERTY_DAMAGE[0];
  const pi = PERSONAL_INJURY.find((o) => o.value === coverage.personalInjury) ?? PERSONAL_INJURY[0];
  const vc = VEHICLE_COVER.find((o) => o.value === coverage.vehicleCover) ?? VEHICLE_COVER[0];

  const months = ageInMonths(vehicle.firstRegYear, vehicle.firstRegMonth);
  const value = agreedValue(model.newPrice, months);

  const biAmount = round10(bi.base * CLASS_FACTOR[model.cls.bi]);
  const pdAmount = round10(pd.base * CLASS_FACTOR[model.cls.pd]);
  const piAmount = round10(pi.base * CLASS_FACTOR[model.cls.pi]);
  const vehAmount = vc.rate === 0 ? 0 : round10(value * vc.rate * CLASS_FACTOR[model.cls.veh]);

  const coverageLines: PremiumLine[] = [
    {
      key: "bi",
      label: `対人賠償 ${bi.label}`,
      note: `基準 ${bi.base.toLocaleString("ja-JP")}円 × 料率クラス${model.cls.bi}（×${CLASS_FACTOR[model.cls.bi]}）`,
      amount: biAmount,
      kind: "add",
    },
    {
      key: "pd",
      label: `対物賠償 ${pd.label}`,
      note: `基準 ${pd.base.toLocaleString("ja-JP")}円 × 料率クラス${model.cls.pd}（×${CLASS_FACTOR[model.cls.pd]}）`,
      amount: pdAmount,
      kind: "add",
    },
    {
      key: "pi",
      label: `人身傷害 ${pi.label}`,
      note:
        pi.base === 0
          ? "付けていないため 0円"
          : `基準 ${pi.base.toLocaleString("ja-JP")}円 × 料率クラス${model.cls.pi}（×${CLASS_FACTOR[model.cls.pi]}）`,
      amount: piAmount,
      kind: "add",
    },
    {
      key: "veh",
      label: `車両保険 ${vc.label}`,
      note:
        vc.rate === 0
          ? "付けていないため 0円"
          : `協定保険価額 ${value.toLocaleString("ja-JP")}円 × ${(vc.rate * 100).toFixed(1)}% × 料率クラス${model.cls.veh}（×${CLASS_FACTOR[model.cls.veh]}）`,
      amount: vehAmount,
      kind: "add",
    },
  ];
  const coverageSubtotal = biAmount + pdAmount + piAmount + vehAmount;

  const ded1 = DEDUCTIBLE_FIRST.find((o) => o.value === coverage.deductibleFirst) ?? DEDUCTIBLE_FIRST[0];
  const ded2 = DEDUCTIBLE_SECOND.find((o) => o.value === coverage.deductibleSecond) ?? DEDUCTIBLE_SECOND[1];
  const dedRate = vehAmount === 0 ? 0 : ded1.rate + ded2.rate;
  const dedAdj = round10(vehAmount * dedRate);

  const afterDed = coverageSubtotal + dedAdj;
  const useOpt = USE_OPTIONS.find((o) => o.value === vehicle.use) ?? USE_OPTIONS[0];
  const milOpt = MILEAGE_OPTIONS.find((o) => o.value === vehicle.mileage) ?? MILEAGE_OPTIONS[2];
  const useAdj = round10(afterDed * (useOpt.factor - 1));
  const milAdj = round10(afterDed * (milOpt.factor - 1));

  const conditionLines: PremiumLine[] = [
    {
      key: "ded",
      label: `車両免責 1回目 ${ded1.label} ／ 2回目以降 ${ded2.label}`,
      note:
        vehAmount === 0
          ? "車両保険を付けていないため調整なし"
          : `車両保険料 ${vehAmount.toLocaleString("ja-JP")}円 の ${pct(dedRate)}（1回目 ${pct(ded1.rate)}・2回目以降 ${pct(ded2.rate)}）`,
      amount: dedAdj,
      kind: dedAdj < 0 ? "subtract" : "add",
    },
    {
      key: "use",
      label: `用途 ${useOpt.label}`,
      note: `補償計 ${afterDed.toLocaleString("ja-JP")}円 × 用途係数 ${useOpt.factor.toFixed(2)}`,
      amount: useAdj,
      kind: useAdj < 0 ? "subtract" : "add",
    },
    {
      key: "mileage",
      label: `年間走行距離 ${milOpt.label}`,
      note: `補償計 ${afterDed.toLocaleString("ja-JP")}円 × 距離係数 ${milOpt.factor.toFixed(2)}`,
      amount: milAdj,
      kind: milAdj < 0 ? "subtract" : "add",
    },
  ];
  const baseBeforeGrade = afterDed + useAdj + milAdj;

  const gRate = gradeRate(holder.grade, holder.hadAccident);
  const gradeAdj = round10(baseBeforeGrade * gRate);
  const afterGrade = baseBeforeGrade + gradeAdj;

  const color = LICENSE_COLORS.find((o) => o.value === holder.licenseColor) ?? LICENSE_COLORS[2];
  const colorAdj = round10(afterGrade * color.rate);

  const discountLines: PremiumLine[] = [
    {
      key: "grade",
      label: `ノンフリート${holder.grade}等級（${holder.hadAccident ? "事故有" : "無事故"}）`,
      note: `等級適用前 ${baseBeforeGrade.toLocaleString("ja-JP")}円 の ${pct(gRate)}`,
      amount: gradeAdj,
      kind: gradeAdj < 0 ? "subtract" : "add",
    },
    {
      key: "license",
      label: `免許証の色 ${color.label}`,
      note: color.rate === 0 ? "割引の対象外" : `等級適用後 ${afterGrade.toLocaleString("ja-JP")}円 の ${pct(color.rate)}`,
      amount: colorAdj,
      kind: colorAdj < 0 ? "subtract" : "add",
    },
  ];

  let safetyTotal = 0;
  for (const device of SAFETY_DEVICES) {
    if (!vehicle.safety.includes(device.id)) continue;
    if (device.needsVehicleCover && vehAmount === 0) continue;
    const adj = round10(afterGrade * device.rate);
    safetyTotal += adj;
    discountLines.push({
      key: `safety-${device.id}`,
      label: device.label,
      note: `等級適用後 ${afterGrade.toLocaleString("ja-JP")}円 の ${pct(device.rate)}`,
      amount: adj,
      kind: "subtract",
    });
  }

  const isNewCar = months <= 25;
  const newCarAdj = isNewCar ? round10(afterGrade * -0.06) : 0;
  if (isNewCar) {
    discountLines.push({
      key: "newcar",
      label: "新車割引",
      note: `初度登録から ${months}か月（25か月以内）／ 等級適用後の −6.0%`,
      amount: newCarAdj,
      kind: "subtract",
    });
  }

  const basePremium = afterGrade + colorAdj + safetyTotal + newCarAdj;

  const appliedRiders = coverage.riders
    .map((id) => findRider(id))
    .filter((r): r is Rider => Boolean(r))
    .filter((r) => !(r.needsVehicleCover && vehAmount === 0));

  const riderLines: PremiumLine[] = appliedRiders.map((r) => ({
    key: `rider-${r.id}`,
    label: r.label,
    note: r.description,
    amount: r.premium,
    kind: "add",
  }));
  const riderTotal = riderLines.reduce((sum, line) => sum + line.amount, 0);

  const fixedLines: PremiumLine[] = [];
  if (options.paperless) {
    fixedLines.push({
      key: "paperless",
      label: "証券不発行割引",
      note: "紙の保険証券を発行しない契約に、定額 1,200円",
      amount: -1200,
      kind: "subtract",
    });
  }
  const fixedTotal = fixedLines.reduce((sum, line) => sum + line.amount, 0);

  const annual = Math.max(0, basePremium + riderTotal + fixedTotal);
  const monthly = Math.ceil((annual * 1.05) / 12 / 10) * 10;
  const monthlyYearTotal = monthly * 12;

  return {
    coverageLines,
    coverageSubtotal,
    conditionLines,
    baseBeforeGrade,
    discountLines,
    basePremium,
    riderLines,
    riderTotal,
    fixedLines,
    annual,
    monthly,
    monthlyYearTotal,
    monthlyExtra: monthlyYearTotal - annual,
    agreedValue: value,
    vehicleBase: vehAmount,
    appliedRiders,
  };
}

