/** 有効期限まで何日か。null（未設定）は対象外。 */
export function daysUntil(expiresAt: string | null): number | null {
  if (!expiresAt) return null;
  const from = todayDate().getTime();
  const to = parseLocalDate(expiresAt).getTime();
  return Math.round((to - from) / 86400000);
}

/** 有効期限が近い（14日以内）見積かどうか。 */
export function isExpiringSoon(row: QuoteRow): boolean {
  const days = daysUntil(row.expiresAt);
  return days !== null && days >= 0 && days <= 14;
}

/** 確定した見積の有効期限（確定日から30日後）。 */
export function expiryFromToday(days = 30): string {
  const base = todayDate();
  base.setDate(base.getDate() + days);
  const y = base.getFullYear();
  const m = String(base.getMonth() + 1).padStart(2, "0");
  const d = String(base.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

"use client";

import * as React from "react";
import {
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Cluster,
  DataTable,
  EmptyState,
  ExpiryBadge,
  FilterChips,
  HStack,
  Skeleton,
  StatGroup,
  VStack,
  formatCurrency,
  type ColumnDef,
} from "@gunjo/ui";
import {
  IconClockExclamation,
  IconFileText,
  IconPencil,
  IconSend,
} from "@tabler/icons-react";

import { TODAY, isExpiringSoon, type QuoteRow } from "./pricing";

export type ListDisplayState = "data" | "loading" | "empty";
type StatusFilter = "all" | "draft" | "presented" | "expiring";

const STATUS_BADGE: Record<QuoteRow["status"], { label: string; variant: "secondary" | "info"; icon: React.ReactNode }> = {
  draft: { label: "作成中", variant: "secondary", icon: <IconPencil /> },
  presented: { label: "提示済み", variant: "info", icon: <IconSend /> },
};

function StatusPill({ status }: { status: QuoteRow["status"] }) {
  const meta = STATUS_BADGE[status];
  return (
    <Badge variant={meta.variant} icon={meta.icon} size="sm">
      {meta.label}
    </Badge>
  );
}

export interface QuoteListProps {
  rows: QuoteRow[];
  displayState: ListDisplayState;
  onOpen: (row: QuoteRow) => void;
  onCreate: () => void;
  /** 一覧の下に置く操作（デモの表示切替など）。 */
  toolbar?: React.ReactNode;
}

export function QuoteList({ rows, displayState, onOpen, onCreate, toolbar }: QuoteListProps) {
  const [filter, setFilter] = React.useState<StatusFilter>("all");

  const counts = React.useMemo(
    () => ({
      all: rows.length,
      draft: rows.filter((r) => r.status === "draft").length,
      presented: rows.filter((r) => r.status === "presented").length,
      expiring: rows.filter(isExpiringSoon).length,
    }),
    [rows],
  );

  const visible = React.useMemo(() => {
    if (filter === "all") return rows;
    if (filter === "expiring") return rows.filter(isExpiringSoon);
    return rows.filter((r) => r.status === filter);
  }, [rows, filter]);

  const columns = React.useMemo<ColumnDef<QuoteRow>[]>(
    () => [
      {
        accessorKey: "number",
        header: "見積番号",
        cell: ({ row }) => <span className="whitespace-nowrap font-medium tabular-nums">{row.original.number}</span>,
      },
      {
        accessorKey: "contractor",
        header: "契約者",
        cell: ({ row }) => <span className="whitespace-nowrap">{row.original.contractor} 様</span>,
      },
      {
        accessorKey: "modelCode",
        header: "型式",
        cell: ({ row }) => <span className="whitespace-nowrap tabular-nums">{row.original.modelCode}</span>,
      },
      {
        accessorKey: "status",
        header: "状態",
        cell: ({ row }) => <StatusPill status={row.original.status} />,
      },
      {
        accessorKey: "agent",
        header: "担当者",
        cell: ({ row }) => <span className="whitespace-nowrap">{row.original.agent}</span>,
      },
      {
        accessorKey: "createdAt",
        header: "作成日",
        cell: ({ row }) => <span className="whitespace-nowrap tabular-nums">{row.original.createdAt}</span>,
      },
      {
        accessorKey: "expiresAt",
        header: "有効期限",
        cell: ({ row }) => (
          <ExpiryBadge
            value={row.original.expiresAt}
            today={TODAY}
            warnWithinDays={14}
            stateClassName="shrink-0"
            className="whitespace-nowrap"
          />
        ),
      },
      {
        accessorKey: "annual",
        header: "年間保険料",
        cell: ({ row }) => (
          <span className="block whitespace-nowrap text-right font-semibold tabular-nums">
            {formatCurrency(row.original.annual)}
          </span>
        ),
      },
    ],
    [],
  );

  const renderCard = React.useCallback(
    (row: QuoteRow) => (
      <VStack gap={2} className="w-full">
        <HStack justify="between" align="start" gap={2} className="w-full">
          <VStack gap={1} className="min-w-0">
            <span className="text-sm font-semibold">{row.contractor} 様</span>
            <span className="text-xs tabular-nums text-muted-foreground">
              {row.number} ／ 型式 {row.modelCode}
            </span>
          </VStack>
          <StatusPill status={row.status} />
        </HStack>
        <ExpiryBadge value={row.expiresAt} today={TODAY} warnWithinDays={14} />
        <HStack justify="between" align="baseline" gap={2} className="w-full">
          <span className="text-xs text-muted-foreground">
            担当 {row.agent} ／ 作成 {row.createdAt}
          </span>
          <span className="text-sm font-semibold tabular-nums">{formatCurrency(row.annual)}</span>
        </HStack>
      </VStack>
    ),
    [],
  );

  return (
    <VStack gap={4}>
      <StatGroup
        cols={{ base: 2, md: 4 }}
        items={[
          { label: "作成中", value: `${counts.draft}件`, hint: "まだ提示していない見積" },
          { label: "提示済み", value: `${counts.presented}件`, hint: "客に渡した見積" },
          {
            label: "有効期限が近い",
            value: `${counts.expiring}件`,
            hint: "期限まで14日以内",
          },
          {
            label: "見積保険料の合計",
            value: formatCurrency(rows.reduce((sum, r) => sum + r.annual, 0)),
            hint: "一覧に出ている見積の年間保険料",
          },
        ]}
      />

      <Card>
        <CardHeader>
          <Cluster justify="between" align="center" gap={3}>
            <div className="min-w-0">
              <CardTitle as="h3">見積の一覧</CardTitle>
              <CardDescription>行を選ぶと、その見積の条件を下の作成画面に読み込みます。</CardDescription>
            </div>
            <Button variant="primary" onClick={onCreate}>
              新しい見積を作る
            </Button>
          </Cluster>
        </CardHeader>
        <CardContent>
          <VStack gap={4}>
            {toolbar}

            {displayState === "loading" ? (
              <div role="status" aria-live="polite" aria-busy="true" className="w-full">
                <span className="sr-only">見積の一覧を読み込んでいます。</span>
                <VStack gap={3} aria-hidden="true">
                  <Skeleton shape="rectangle" className="h-9 w-full max-w-72" />
                  {Array.from({ length: 6 }).map((_, i) => (
                    <HStack key={i} gap={3} align="center" className="w-full">
                      <Skeleton shape="rectangle" className="h-5 w-28 shrink-0" />
                      <Skeleton shape="rectangle" className="h-5 flex-1" />
                      <Skeleton shape="rectangle" className="h-5 w-20 shrink-0" />
                      <Skeleton shape="rectangle" className="hidden h-5 w-24 shrink-0 sm:block" />
                    </HStack>
                  ))}
                </VStack>
              </div>
            ) : displayState === "empty" || rows.length === 0 ? (
              <EmptyState
                headingLevel={4}
                icon={<IconFileText aria-hidden="true" />}
                title="見積はまだ1件もありません"
                description="契約者と車両の情報を入れると、保険料の試算がその場で始まります。"
                action={
                  <Button variant="primary" onClick={onCreate}>
                    最初の見積を作る
                  </Button>
                }
              />
            ) : (
              <>
                <FilterChips
                  aria-label="見積の状態でしぼり込む"
                  value={filter}
                  onValueChange={(v) => setFilter(v as StatusFilter)}
                  items={[
                    { value: "all", label: "すべて", count: counts.all },
                    { value: "draft", label: "作成中", count: counts.draft },
                    { value: "presented", label: "提示済み", count: counts.presented },
                    {
                      value: "expiring",
                      label: "有効期限が近い",
                      count: counts.expiring,
                      icon: <IconClockExclamation size={16} />,
                    },
                  ]}
                />

                {visible.length === 0 ? (
                  <EmptyState
                    headingLevel={4}
                    title="このしぼり込みに合う見積はありません"
                    description="別の状態を選ぶか、「すべて」に戻してください。"
                    action={
                      <Button variant="outline" onClick={() => setFilter("all")}>
                        すべてを表示する
                      </Button>
                    }
                  />
                ) : (
                  <DataTable
                    columns={columns}
                    data={visible}
                    caption="進行中の見積"
                    captionClassName="sr-only"
                    filter={{ columnId: "contractor", placeholder: "契約者名でしぼり込む" }}
                    pageSize={10}
                    onRowClick={onOpen}
                    renderCard={renderCard}
                  />
                )}
              </>
            )}
          </VStack>
        </CardContent>
      </Card>
    </VStack>
  );
}
